namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Algebra.StateApproximation;

internal sealed class StateApproximationS3QuantumAlgebraStateApproximationPhysicslib4GNSIrreducibilityDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Pure cyclic representations and commutants", H("Pure cyclic representations and commutants"), Blocks(
        Paragraph(Text("A cyclic representation reproducing a pure state has scalar commutant: every bounded operator commuting with all represented elements is a complex scalar multiple of the identity. Consequently its bicommutant is all bounded operators. The Hilbert space and algebra are arbitrary in their respective universes, with no finite-dimensional or separability restriction.")),
        Describe.Lean(DescribeId.Create("statement0"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/Irreducibility.gns_construction"),
            H("gns_construction"), StatementSource.FromAuthor(Disp(Statement0())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Give A its spectral order and apply Mathlib's PositiveLinearMap GNS construction to State.toPositiveLinearMap. Take Omega to be the completed image of 1; left multiplication sends it to the image of a, so UniformSpace.Completion.denseRange_coe proves cyclicity and preGNS_inner_def gives the moment identity. If omega is faithful, equality of represented operators makes the squared GNS norm of a-b zero, contradicting strict positivity unless a=b. The completion stays in the universe of A."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement1"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/Irreducibility.eq_smul_one_of_commute_of_cyclic"),
            H("eq_smul_one_of_commute_of_cyclic"), StatementSource.FromAuthor(Disp(Statement1())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Move pi(b) from the first inner-product slot to pi(star b) in the second, commute T through that operator, and apply the proportional coefficient hypothesis at star b*a. Thus T and scalar multiplication by c have the same inner products against every cyclic-orbit vector. DenseRange.eq_of_inner_right identifies their values on the orbit, and Continuous.ext_on extends equality to all of H."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement2"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/Irreducibility.coeffFunctional_apply"),
            H("coeffFunctional_apply"), StatementSource.FromAuthor(Disp(Statement2())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The continuous functional coeffFunctional is obtained by LinearMap.mkContinuous from the coefficient a mapped to inner(Omega,T(pi(a)Omega)). Evaluation retains that defining linear map, so the asserted identity is definitional. The continuity bound used in the definition is norm(Omega) squared times norm(T), using contractivity of pi."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement3"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/Irreducibility.coeffFunctional_star_mul"),
            H("coeffFunctional_star_mul"), StatementSource.FromAuthor(Disp(Statement3())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Expand pi(star a*a) as pi(star a) composed with pi(a), and use the commutant hypothesis to move T past pi(star a). The identity map_star turns pi(star a) into the adjoint of pi(a); ContinuousLinearMap.adjoint_inner_right then transfers it to the first slot."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement4"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/Irreducibility.isPositive_inner_nonneg"),
            H("isPositive_inner_nonneg"), StatementSource.FromAuthor(Disp(Statement4())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The real part is nonnegative by IsPositive.re_inner_nonneg_right. Symmetry of the positive operator, together with inner_conj_symm, makes the diagonal coefficient equal to its conjugate, so Complex.conj_eq_iff_im forces its imaginary part to be zero. Complex.le_def combines these facts; completeness is unnecessary."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement5"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/Irreducibility.scalar_of_isSelfAdjoint_of_isPure"),
            H("scalar_of_isSelfAdjoint_of_isPure"), StatementSource.FromAuthor(Disp(Statement5())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Choose r>0 with r norm(S) at most one half and set T=r S+one half times the identity. The operator norm estimate bounds every diagonal quadratic form between 0 and norm(v) squared, proving positivity of T and 1-T. By coeffFunctional_star_mul and isPositive_inner_nonneg, the coefficient functional of T is positive and dominated by omega. Purity makes it proportional to omega, eq_smul_one_of_commute_of_cyclic makes T scalar, and solving the affine relation makes S scalar."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement6"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/Irreducibility.isIrreducible_of_isPure"),
            H("isIrreducible_of_isPure"), StatementSource.FromAuthor(Disp(Statement6())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Taking adjoints of the commutation relation shows that star T also commutes with the representation. Hence the self-adjoint operators T+star T and i(star T-T) commute as well. Apply scalar_of_isSelfAdjoint_of_isPure to each, then reconstruct T as one half times the sum of the first and i times the second."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement7"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/Irreducibility.gnsVonNeumann_eq_univ_of_isIrreducible"),
            H("gnsVonNeumann_eq_univ_of_isIrreducible"), StatementSource.FromAuthor(Disp(Statement7())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Irreducibility identifies the centralizer of the representation's range with scalar multiples of 1; smul_one_mem_centralizer supplies the converse inclusion. Every bounded operator commutes with such scalars, so the centralizer of this centralizer is the entire operator space. This proves the full bicommutant equality, beyond a statement only about its center."))), DescribeRole.Theorem))));

